import{_ as t,o,c as a,a3 as d}from"./chunks/framework.DH50UWNB.js";const u=JSON.parse('{"title":"Connect Claude Code to Wake","description":"How to connect a repository to Claude Code with wake connect claude-code: the commands you get, the files it writes, signing in and updates.","frontmatter":{"title":"Connect Claude Code to Wake","description":"How to connect a repository to Claude Code with wake connect claude-code: the commands you get, the files it writes, signing in and updates."},"headers":[],"relativePath":"agents/claude-code.md","filePath":"agents/claude-code.md","lastUpdated":1794486859000}'),i={name:"agents/claude-code.md"};function s(n,e,c,l,r,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h1><p>Connect a repository to Claude Code from its directory:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line prompt"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wake</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> connect</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> claude-code</span></span></code></pre></div><p><code>wake setup --agent claude-code</code> runs it for you. Commit the files it writes.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><p>Five commands you type in Claude Code:</p><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>/wake:next</code></td><td>Proposes the next free task and claims it once you confirm</td></tr><tr><td><code>/wake:status</code></td><td>Shows the tasks this session holds, the free ones and what is left in the open milestone; changes nothing</td></tr><tr><td><code>/wake:plan &lt;idea&gt;</code></td><td>Plans the idea with the repository&#39;s planning method, without writing code</td></tr><tr><td><code>/wake:done</code></td><td>Runs the repository&#39;s checks, attaches evidence and completes the task this session holds</td></tr><tr><td><code>/wake:release</code></td><td>Releases the open milestone with the repository&#39;s own process, asking before every push, tag or publish</td></tr></tbody></table><p>The <code>wake</code> and <code>wake-planning</code> skills tell Claude Code how to claim, plan and finish work. Hooks run <code>wake hook</code> when a session starts, after each tool call and when it ends, with the <a href="/wake-dist/docs/start/cli#sign-in">CLI&#39;s sign-in</a>, so the CLI must be installed and signed in on this machine.</p><h2 id="files-it-writes" tabindex="-1">Files it writes <a class="header-anchor" href="#files-it-writes" aria-label="Permalink to &quot;Files it writes&quot;">​</a></h2><ul><li><code>.mcp.json</code>: Wake&#39;s MCP server, <code>wake</code>, at <code>&lt;your Wake URL&gt;/mcp</code>.</li><li><code>.claude/settings.json</code>: Wake&#39;s plugin marketplace, with auto-update on, and the <code>wake</code> plugin, which brings the hooks, the skills and the commands.</li><li>The Wake block in <code>CLAUDE.md</code>, or in <code>AGENTS.md</code> when <code>CLAUDE.md</code> imports it with a line <code>@AGENTS.md</code> or when the repository has only <code>AGENTS.md</code>.</li></ul><p>No file holds a token. Claude Code fetches the marketplace and the plugin from the public repository <code>https://github.com/dalodev/wake-dist.git</code>: no GitHub account is needed.</p><h2 id="sign-in" tabindex="-1">Sign in <a class="header-anchor" href="#sign-in" aria-label="Permalink to &quot;Sign in&quot;">​</a></h2><ol><li>Open Claude Code in the repository and trust the folder when it asks. Claude Code reads the project&#39;s MCP server, marketplace and plugin only after you trust it.</li><li>Accept the <code>wake</code> MCP server and install the <code>wake</code> plugin when Claude Code offers them. If you dismissed the plugin, run <code>/plugin</code>, find <code>wake</code> in the <code>wake</code> marketplace and install it, or run <code>claude plugin install wake@wake --scope project</code> in the repository; without it, no Wake hook or command runs.</li><li>Run <code>/mcp</code>, choose <code>wake</code> and allow Claude Code in the browser.</li></ol><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><p>Claude Code updates the <code>wake</code> plugin by itself, in the background after start-up, whenever a stable Wake release ships. There is nothing to commit. A repository connected by an older Wake may need one more step: see <a href="/wake-dist/docs/run/older-installations">Older installations</a>.</p>',15)])])}const k=t(i,[["render",s]]);export{u as __pageData,k as default};
